<script setup>defineProps({active:String,labels:Object});defineEmits(['select']);const icons={users:'♙',vehicles:'▣',routes:'⌁',trips:'▤','trip-stops':'⌖',addons:'＋',promotions:'◇',bookings:'▦',payments:'▱',provinces:'◎',stations:'⌂'};</script><template><aside class="admin-sidebar"><div class="logo admin-logo"><span>F</span><div>FastTravel Admin</div></div><nav><button :class="{active:active==='dashboard'}" @click="$emit('select','dashboard')">⌂ Dashboard</button><button v-for="(label,key) in labels" :key="key" :class="{active:active===key}" @click="$emit('select',key)"><i>{{icons[key]||'▦'}}</i> Quản lý {{label.toLowerCase()}}</button><RouterLink to="/">← Về website</RouterLink></nav></aside></template>
